from _h import *
DAY = 19

def FB(id, q, ans, explain):
    return fill(id, q, ans if isinstance(ans, list) else [ans], explain)

def PICK(id, q, opts, ans, explain, keys):
    return mcq(id, q, opts, ans, explain, keys=keys)

N4 = ["1", "2", "3", "4"]
AB = ["a", "b"]
ABC = ["a", "b", "c"]
WAGA = ["は", "が"]
MATOME = "まとめ　次の文章を読んで、文章全体の内容を考えて、1から5の中に入る最もよいものを1・2・3・4から一つ選びなさい。"

def P3(id, label, opts, ans, ex):
    return PICK(id, label, opts, ans, ex, ABC[:len(opts)])

def WG(id, label, ans, ex):
    """は／が choice; ans may be 0, 1 or 'both'."""
    if ans == "both":
        return PICK(id, label, ["は", "が", "どちらも可"], 2, ex, ["", "", ""])
    return PICK(id, label, WAGA, ans, ex, ["", ""])

